<section class="page-intro shell"><span class="eyebrow">ALLSTORE CATALOG</span><h1>পছন্দ খুঁজে নিন।</h1><p>Supabase-এ থাকা active পণ্য, category ও brand থেকে ফলাফল দেখানো হচ্ছে।</p><form class="shop-filters shop-filters-wide" method="get" action="/shop"><label class="sr-only" for="filter-q">পণ্য খুঁজুন</label><input id="filter-q" type="search" name="q" value="<?= e($data['search']) ?>" placeholder="নাম, SKU বা শব্দ দিয়ে খুঁজুন"><label class="sr-only" for="filter-category">বিভাগ</label><select id="filter-category" name="category"><option value="">সব বিভাগ</option><?php foreach(($data['categories']??[]) as $category): ?><option value="<?= e($category['slug']) ?>" <?= $data['category']===$category['slug']?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select><label class="sr-only" for="filter-brand">ব্র্যান্ড</label><select id="filter-brand" name="brand"><option value="">সব brand</option><?php foreach(($data['brands']??[]) as $brand): ?><option value="<?= e($brand['slug']) ?>" <?= $data['brand']===$brand['slug']?'selected':'' ?>><?= e($brand['name']) ?></option><?php endforeach; ?></select><label class="sr-only" for="filter-sort">সাজান</label><select id="filter-sort" name="sort"><option value="featured" <?= $data['sort']==='featured'?'selected':'' ?>>বাছাই</option><option value="newest" <?= $data['sort']==='newest'?'selected':'' ?>>নতুন</option><option value="price_asc" <?= $data['sort']==='price_asc'?'selected':'' ?>>দাম: কম থেকে বেশি</option><option value="price_desc" <?= $data['sort']==='price_desc'?'selected':'' ?>>দাম: বেশি থেকে কম</option><option value="popular" <?= $data['sort']==='popular'?'selected':'' ?>>জনপ্রিয়</option></select><button class="button button-green" type="submit">খুঁজুন</button></form></section><section class="section product-section"><div class="shell"><div class="section-heading listing-heading"><div><span class="eyebrow"><?= $data['search']!==''?'SEARCH RESULTS':'CURATED FOR YOU' ?></span><h2><?= $data['search']!==''?'“'.e($data['search']).'”':'সব পণ্য' ?></h2></div><span class="muted"><?= (int)($data['product_total']??0) ?>টি ফলাফল · <?= (int)$data['page'] ?> / <?= max(1,(int)ceil(($data['product_total']??0)/24)) ?></span></div><?php require __DIR__.'/product-grid.php'; ?><?php $pages=max(1,(int)ceil(($data['product_total']??0)/24));if($pages>1): ?><nav class="pagination" aria-label="পণ্যের পৃষ্ঠা"><?php if($data['page']>1): ?><a href="<?= e('/shop?'.http_build_query(['q'=>$data['search'],'category'=>$data['category'],'brand'=>$data['brand'],'sort'=>$data['sort'],'page'=>$data['page']-1])) ?>">← আগের</a><?php endif; ?><span>পৃষ্ঠা <?= (int)$data['page'] ?> / <?= $pages ?></span><?php if($data['page']<$pages): ?><a href="<?= e('/shop?'.http_build_query(['q'=>$data['search'],'category'=>$data['category'],'brand'=>$data['brand'],'sort'=>$data['sort'],'page'=>$data['page']+1])) ?>">পরের →</a><?php endif; ?></nav><?php endif; ?></div></section>
